use vstd::prelude::*;

verus! {
    /// Given n ≥ 1, constructs a string of length n over {'a', 'b'}
    /// such that for all 0 ≤ i ≤ n−3, s[i] ≠ s[i+2].
    /// We never use 'c', thus minimizing its usage to zero.
    pub fn solve(n: i8) -> Vec<char>
        #[verifier::requires(n >= 1)]
        #[verifier::ensures(|res: &Vec<char>| res.len() == n as usize)]
        #[verifier::ensures(|res: &Vec<char>|
            forall(|i: usize| i + 2 < res.len() ==> res[i] != res[i+2])
        )]
        #[verifier::ensures(|res: &Vec<char>|
            forall(|i: usize| i < res.len() ==> res[i] == 'a' || res[i] == 'b')
        )]
    {
        let mut result: Vec<char> = Vec::new();
        let mut i: i8 = 0;
        // Build the string one character at a time.
        while i < n {
            // i always in [0, n]
            invariant 0 <= i && i <= n;
            // result.len() == i at the start of each iteration
            invariant result.len() == i as usize;
            // All characters so far are 'a' or 'b'
            invariant forall(|j: usize| j < result.len() ==>
                result[j] == 'a' || result[j] == 'b'
            );
            // No two-apart equal characters so far
            invariant forall(|j: usize| j + 2 < result.len() ==>
                result[j] != result[j+2]
            );
            // Measures termination: n - i decreases each loop
            decreases n - i;

            // Determine which character to push:
            // Group positions in pairs [0,1], [2,3], [4,5], ...
            // In each pair we use the same letter, and alternate pairs:
            // "aa", "bb", "aa", "bb", ...
            let k: usize = (i / 2) as usize;
            let c: char;
            if k % 2 == 0 {
                c = 'a';
            } else {
                c = 'b';
            }

            // Prove that the new character c differs from the character
            // two positions before (if that exists).
            if i >= 2 {
                let j_prev: usize = (i - 2) as usize;
                let k_prev: usize = ((i - 2) / 2) as usize;
                // By integer division properties:
                // floor(i/2) = k, floor((i-2)/2) = k_prev = k - 1
                assert(k_prev + 1 == k);
                // Parity flips when subtracting 1
                assert(k_prev % 2 != k % 2);
                // Hence the character at j_prev (built with k_prev)
                // differs from c.
                assert(result[j_prev] != c);
            }

            result.push(c);
            i += 1;
        }

        result
    }
}